namespace fs=std::filesystem;
static void safePath(fs::path value){for(;!value.empty();value=value.parent_path()){const auto attributes=GetFileAttributesW(value.c_str());if(attributes!=INVALID_FILE_ATTRIBUTES&&(attributes&FILE_ATTRIBUTE_REPARSE_POINT))throw std::runtime_error("Ligacao simbolica na atualizacao");if(value==value.root_path())break;}}
static std::wstring registryString(HKEY key,const wchar_t* name){wchar_t value[32768];DWORD bytes=sizeof(value),type=0;if(RegQueryValueExW(key,name,nullptr,&type,reinterpret_cast<BYTE*>(value),&bytes)!=ERROR_SUCCESS||type!=REG_SZ||bytes<sizeof(wchar_t)||bytes>sizeof(value))return {};value[(bytes/sizeof(wchar_t))-1]=0;return value;}
static HKEY installationRegistration(const fs::path& app,REGSAM access){
 for(const auto view:{KEY_WOW64_32KEY,KEY_WOW64_64KEY}){HKEY key=nullptr;if(RegOpenKeyExW(HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Nexo AI",0,access|view,&key)!=ERROR_SUCCESS)continue;auto location=registryString(key,L"InstallLocation");if(location.size()>1&&location.front()==L'"'&&location.back()==L'"')location=location.substr(1,location.size()-2);const bool matches=registryString(key,L"DisplayName")==L"Nexo AI"&&registryString(key,L"MainBinaryName")==L"nexo-ai.exe"&&!location.empty()&&_wcsicmp(fs::absolute(location).lexically_normal().c_str(),app.c_str())==0;if(matches)return key;RegCloseKey(key);}return nullptr;
}
static void restoreRegistration(const fs::path& app,const fs::path& rollback){
 std::string narrow;std::ifstream(rollback/L"version.txt")>>narrow;if(!std::regex_match(narrow,std::regex("[0-9]+\\.[0-9]+\\.[0-9]+")))throw std::runtime_error("Versao de recuperacao invalida");
 HKEY key=installationRegistration(app,KEY_QUERY_VALUE|KEY_SET_VALUE);if(!key)return;const std::wstring version(narrow.begin(),narrow.end());const auto status=RegSetValueExW(key,L"DisplayVersion",0,REG_SZ,reinterpret_cast<const BYTE*>(version.c_str()),static_cast<DWORD>((version.size()+1)*sizeof(wchar_t)));RegCloseKey(key);if(status!=ERROR_SUCCESS)throw std::runtime_error("Ficheiros recuperados; nao foi possivel repor a versao no Windows");
}
static fs::path ownPath(){wchar_t value[32768];const DWORD length=GetModuleFileNameW(nullptr,value,32768);if(!length||length>=32768)throw std::runtime_error("Caminho do recuperador invalido");return fs::path(value);}
class Digest {
 BCRYPT_ALG_HANDLE algorithm=nullptr;BCRYPT_HASH_HANDLE handle=nullptr;std::vector<BYTE> object;
 public:Digest(){DWORD length=0,size=0;if(BCryptOpenAlgorithmProvider(&algorithm,BCRYPT_SHA256_ALGORITHM,nullptr,0)!=0||BCryptGetProperty(algorithm,BCRYPT_OBJECT_LENGTH,reinterpret_cast<BYTE*>(&length),sizeof(length),&size,0)!=0)throw std::runtime_error("Hash indisponivel");object.resize(length);if(BCryptCreateHash(algorithm,&handle,object.data(),length,nullptr,0,0)!=0)throw std::runtime_error("Hash indisponivel");}
 ~Digest(){if(handle)BCryptDestroyHash(handle);if(algorithm)BCryptCloseAlgorithmProvider(algorithm,0);}
 void add(const void* data,size_t size){if(size>0xffffffff||BCryptHashData(handle,reinterpret_cast<PUCHAR>(const_cast<void*>(data)),static_cast<ULONG>(size),0)!=0)throw std::runtime_error("Falha no hash de recuperacao");}
 std::wstring finish(){BYTE bytes[32];if(BCryptFinishHash(handle,bytes,32,0)!=0)throw std::runtime_error("Falha no hash de recuperacao");const wchar_t* hex=L"0123456789abcdef";std::wstring result;for(BYTE byte:bytes){result+=hex[byte>>4];result+=hex[byte&15];}return result;}
};
static std::wstring snapshotHash(const fs::path& root){safePath(root);std::vector<fs::path> files;for(const auto& entry:fs::recursive_directory_iterator(root)){safePath(entry.path());if(entry.is_regular_file())files.push_back(entry.path());}std::sort(files.begin(),files.end());Digest digest;uint64_t total=0;if(files.empty()||files.size()>20000)throw std::runtime_error("Recuperacao incompleta");for(const auto& file:files){const auto relative=fs::relative(file,root).generic_wstring();const uint32_t chars=static_cast<uint32_t>(relative.size());const uint64_t bytes=fs::file_size(file);total+=bytes;if(total>1000000000)throw std::runtime_error("Recuperacao demasiado grande");digest.add(&chars,sizeof(chars));digest.add(relative.data(),relative.size()*sizeof(wchar_t));digest.add(&bytes,sizeof(bytes));std::ifstream input(file,std::ios::binary);char buffer[65536];if(!input)throw std::runtime_error("Ficheiro de recuperacao indisponivel");while(input){input.read(buffer,sizeof(buffer));if(input.gcount())digest.add(buffer,static_cast<size_t>(input.gcount()));}if(!input.eof())throw std::runtime_error("Erro ao ler recuperacao");}return digest.finish();}
static void saveRecovery(const fs::path& app,const fs::path& rollback,const std::wstring& exe,const std::wstring& version){
 const auto digest=snapshotHash(rollback/L"app");const std::wstring text=app.wstring()+L"\n"+exe+L"\n"+version+L"\n"+digest;DATA_BLOB input{static_cast<DWORD>(text.size()*sizeof(wchar_t)),reinterpret_cast<BYTE*>(const_cast<wchar_t*>(text.data()))},output{};
 if(!CryptProtectData(&input,L"Nexo AI recovery",nullptr,nullptr,nullptr,CRYPTPROTECT_UI_FORBIDDEN,&output))throw std::runtime_error("Nao foi possivel proteger a recuperacao");const auto target=rollback.parent_path()/L"recovery.dat";std::ofstream file(target,std::ios::binary);file.write(reinterpret_cast<char*>(output.pbData),output.cbData);const bool ok=static_cast<bool>(file);LocalFree(output.pbData);if(!ok)throw std::runtime_error("Nao foi possivel guardar a recuperacao");
 // A real per-user installation gets a normal Start menu recovery entry.
 if(exe!=L"nexo-ai.exe")return;HKEY key=installationRegistration(app,KEY_QUERY_VALUE);if(!key)return;RegCloseKey(key);
 PWSTR programs=nullptr;if(SHGetKnownFolderPath(FOLDERID_Programs,KF_FLAG_CREATE,nullptr,&programs)!=S_OK)return;const fs::path shortcut=fs::path(programs)/L"Recuperar Nexo AI.lnk";CoTaskMemFree(programs);const HRESULT initialized=CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);IShellLinkW* link=nullptr;if(SUCCEEDED(CoCreateInstance(CLSID_ShellLink,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&link)))){link->SetPath(ownPath().c_str());link->SetArguments(L"--recover");link->SetShowCmd(SW_HIDE);link->SetDescription(L"Restaurar a versao anterior do Nexo AI");IPersistFile* persisted=nullptr;if(SUCCEEDED(link->QueryInterface(IID_PPV_ARGS(&persisted)))){persisted->Save(shortcut.c_str(),TRUE);persisted->Release();}link->Release();}if(SUCCEEDED(initialized))CoUninitialize();
}
static std::wstring quote(const std::wstring& text){std::wstring out=L"\"";unsigned slashes=0;for(wchar_t c:text){if(c==L'\\'){slashes++;continue;}if(c==L'\"'){out.append(slashes*2+1,L'\\');out+=c;}else{out.append(slashes,L'\\');out+=c;}slashes=0;}out.append(slashes*2,L'\\');return out+L"\"";}
static DWORD run(const fs::path& executable,std::wstring args,bool wait){std::wstring command=quote(executable.wstring())+L" "+args;STARTUPINFOW startup{};startup.cb=sizeof(startup);PROCESS_INFORMATION process{};if(!CreateProcessW(executable.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,executable.parent_path().c_str(),&startup,&process))throw std::runtime_error("Nao foi possivel iniciar o instalador");CloseHandle(process.hThread);DWORD code=0;if(wait){if(WaitForSingleObject(process.hProcess,600000)!=WAIT_OBJECT_0){CloseHandle(process.hProcess);throw std::runtime_error("Tempo limite de instalacao");}GetExitCodeProcess(process.hProcess,&code);}CloseHandle(process.hProcess);return code;}
static void copyTree(const fs::path& from,const fs::path& to){safePath(from);safePath(to);fs::create_directories(to);for(const auto& entry:fs::recursive_directory_iterator(from)){safePath(entry.path());const auto destination=to/fs::relative(entry.path(),from);if(entry.is_directory())fs::create_directories(destination);else if(entry.is_regular_file()){fs::create_directories(destination.parent_path());fs::copy_file(entry.path(),destination,fs::copy_options::overwrite_existing);}}}
static void restoreTree(const fs::path& from,const fs::path& app,const std::wstring& exe){if(!fs::is_regular_file(from/exe))throw std::runtime_error("Recuperacao incompleta");for(const auto& entry:fs::recursive_directory_iterator(from))if(entry.is_symlink())throw std::runtime_error("Ligacao simbolica na recuperacao");for(unsigned retry=0;;retry++){std::error_code error;fs::remove_all(app,error);if(!error)break;if(retry>=149){copyTree(from,app);throw std::runtime_error("A recuperacao aguarda ficheiros ainda abertos. A instalacao anterior foi preservada; fecha a aplicacao e tenta novamente.");}Sleep(200);}copyTree(from,app);}
static bool within(const fs::path& child,const fs::path& parent){const auto relative=child.lexically_relative(parent);return !relative.empty()&&*relative.begin()!=L"..";}
struct Recovery {fs::path app,rollback;std::wstring exe,version;};
static Recovery readRecovery(){const auto folder=ownPath().parent_path(),file=folder/L"recovery.dat";safePath(file);if(!fs::is_regular_file(file)||fs::file_size(file)>131072)throw std::runtime_error("Registo de recuperacao indisponivel");std::ifstream input(file,std::ios::binary);std::vector<BYTE> bytes((std::istreambuf_iterator<char>(input)),{});DATA_BLOB encrypted{static_cast<DWORD>(bytes.size()),bytes.data()},plain{};if(!CryptUnprotectData(&encrypted,nullptr,nullptr,nullptr,nullptr,CRYPTPROTECT_UI_FORBIDDEN,&plain))throw std::runtime_error("Registo de recuperacao alterado ou de outro utilizador");if(plain.cbData%sizeof(wchar_t)){LocalFree(plain.pbData);throw std::runtime_error("Registo de recuperacao invalido");}std::wstring text(reinterpret_cast<wchar_t*>(plain.pbData),plain.cbData/sizeof(wchar_t));LocalFree(plain.pbData);std::vector<std::wstring> fields;size_t start=0;for(;;){const auto end=text.find(L'\n',start);fields.push_back(text.substr(start,end==std::wstring::npos?end:end-start));if(end==std::wstring::npos)break;start=end+1;}if(fields.size()!=4||!std::regex_match(fields[1],std::wregex(L"[A-Za-z0-9._-]+\\.exe"))||!std::regex_match(fields[2],std::wregex(L"[0-9]+\\.[0-9]+\\.[0-9]+"))||!std::regex_match(fields[3],std::wregex(L"[a-f0-9]{64}")))throw std::runtime_error("Registo de recuperacao invalido");Recovery result{fs::absolute(fields[0]).lexically_normal(),folder/L"rollback",fields[1],fields[2]};if(result.app==result.app.root_path()||within(result.app,folder)||within(folder,result.app))throw std::runtime_error("Destino de recuperacao invalido");safePath(result.app);safePath(result.rollback);if(!fs::is_regular_file(result.rollback/L"app"/result.exe)||snapshotHash(result.rollback/L"app")!=fields[3])throw std::runtime_error("Copia de recuperacao incompleta ou alterada");return result;}
static int graphicalRecovery(bool checkOnly){try{const auto record=readRecovery();if(checkOnly)return 0;const auto message=L"Feche o Nexo AI antes de continuar.\n\nRestaurar a versao "+record.version+L" em:\n"+record.app.wstring()+L"\n\nA pasta de dados separada da aplicacao sera preservada. Deseja continuar?";if(MessageBoxW(nullptr,message.c_str(),L"Recuperar Nexo AI",MB_YESNO|MB_ICONQUESTION|MB_DEFBUTTON2)!=IDYES)return 0;restoreTree(record.rollback/L"app",record.app,record.exe);restoreRegistration(record.app,record.rollback);std::ofstream(record.rollback.parent_path()/L"result.txt")<<"completed";run(record.app/record.exe,L"",false);return 0;}catch(const std::exception&){if(!checkOnly)MessageBoxW(nullptr,L"Nao foi possivel validar ou restaurar a copia anterior. Feche o Nexo AI e tente novamente. Uma copia alterada ou incompleta nao sera usada. Os dados separados da aplicacao nao foram apagados.",L"Recuperar Nexo AI",MB_OK|MB_ICONERROR);return 1;}}
int wmain(int argc,wchar_t** argv){
 if(argc==2&&std::wstring(argv[1])==L"--recover")return graphicalRecovery(false);
 if(argc==2&&std::wstring(argv[1])==L"--check-recovery")return graphicalRecovery(true);
 if(argc!=8)return 2;
 const std::wstring mode=argv[1];const DWORD parent=wcstoul(argv[2],nullptr,10);const fs::path app=fs::absolute(argv[3]).lexically_normal(),stage=fs::absolute(argv[4]).lexically_normal(),rollback=fs::absolute(argv[5]).lexically_normal();const std::wstring exe=argv[6],version=argv[7];
 if((mode!=L"install"&&mode!=L"rollback")||!parent||rollback.filename()!=L"rollback"||!std::regex_match(version,std::wregex(L"[0-9]+\\.[0-9]+\\.[0-9]+"))||exe.find_first_of(L"\\/:")!=std::wstring::npos||within(rollback,app)||within(stage,app)||within(app,rollback))return 3;
 try{
  if(app==app.root_path()||app==stage||app==rollback)throw std::runtime_error("Pasta de instalacao invalida");safePath(app);safePath(stage);safePath(rollback);safePath(stage/L"setup.exe");
  HANDLE process=OpenProcess(SYNCHRONIZE,FALSE,parent);if(process){const DWORD result=WaitForSingleObject(process,120000);CloseHandle(process);if(result!=WAIT_OBJECT_0)throw std::runtime_error("A aplicacao nao terminou");}
  if(mode==L"install"){
   if(stage.parent_path().parent_path()!=rollback.parent_path())throw std::runtime_error("Pasta de atualizacao invalida");
   safePath(rollback/L"app");safePath(rollback/L"version.txt");fs::remove_all(rollback/L"app");copyTree(app,rollback/L"app");std::string narrowVersion;for(wchar_t character:version)narrowVersion+=static_cast<char>(character);std::ofstream(rollback/L"version.txt")<<narrowVersion;saveRecovery(app,rollback,exe,version);
   const DWORD code=run(stage/L"setup.exe",L"/S /D="+app.wstring(),true);if(code!=0){restoreTree(rollback/L"app",app,exe);restoreRegistration(app,rollback);throw std::runtime_error("Instalacao falhou; ficheiros anteriores recuperados");}
  }else{if(stage!=rollback)throw std::runtime_error("Recuperacao invalida");restoreTree(rollback/L"app",app,exe);restoreRegistration(app,rollback);}
  std::ofstream(rollback.parent_path()/L"result.txt")<<"completed";
  run(app/exe,L"",false);return 0;
 }catch(const std::exception& error){std::cerr<<error.what()<<std::endl;std::ofstream(rollback.parent_path()/L"result.txt")<<error.what();try{run(app/exe,L"",false);}catch(...){}return 1;}
}
